import type {Booking,Room} from '@/lib/pilot';
export type RoomMoveCommand={p_request:string;p_reservation:string;p_expected_source_version:number;p_from_room:string;p_expected_from_room_version:number;p_to_room:string;p_expected_to_room_version:number;p_reason:string};
export type RoomMoveResult={request_id:string;reservation:Booking;from_room:Room;to_room:Room;moved_at:string;replayed:boolean};
export type MoveStatus={found:boolean;action?:string;result?:{request_id:string;reservation_id:string;from_room_id:string;to_room_id:string;source_version:number;moved_at:string}};
const uuid=(x:unknown)=>typeof x==='string'&&/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(x);
const version=(x:unknown)=>Number.isSafeInteger(x)&&Number(x)>0;
export const roomMoveKey=(actor:string,tenant:string,property:string,reservation:string)=>'iratepilot-pms-pending-room-move:'+actor+':'+tenant+':'+property+':'+reservation;
export function validRoomMove(value:unknown,reservation:string):value is RoomMoveCommand{if(!value||typeof value!=='object'||Array.isArray(value))return false;const p=value as RoomMoveCommand;return Object.keys(p).sort().join(',')==='p_expected_from_room_version,p_expected_source_version,p_expected_to_room_version,p_from_room,p_reason,p_request,p_reservation,p_to_room'&&uuid(p.p_request)&&p.p_reservation===reservation&&uuid(p.p_reservation)&&uuid(p.p_from_room)&&uuid(p.p_to_room)&&p.p_from_room!==p.p_to_room&&version(p.p_expected_source_version)&&version(p.p_expected_from_room_version)&&version(p.p_expected_to_room_version)&&typeof p.p_reason==='string'&&p.p_reason.trim().length>=4&&p.p_reason.length<=500&&!Array.from(p.p_reason).some(c=>c.charCodeAt(0)<32||c.charCodeAt(0)===127)}
export function validateMoveReceipt(status:MoveStatus,p:RoomMoveCommand){const r=status.result;if(!status.found||status.action!=='move_room'||!r||r.request_id!==p.p_request||r.reservation_id!==p.p_reservation||r.from_room_id!==p.p_from_room||r.to_room_id!==p.p_to_room||r.source_version!==p.p_expected_source_version||typeof r.moved_at!=='string'||!Number.isFinite(Date.parse(r.moved_at)))throw Error('The saved move receipt does not match this request. Reconcile the assignment before continuing.');}
